CREATE DATABASE IF NOT EXISTS bloodbank_db;
USE bloodbank_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS blood_requests;
DROP TABLE IF EXISTS blood_stock;
DROP TABLE IF EXISTS donors;
DROP TABLE IF EXISTS admins;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE admins(id INT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL);
CREATE TABLE donors(id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, phone VARCHAR(20) NOT NULL, age INT NOT NULL, gender VARCHAR(30), blood_group VARCHAR(5) NOT NULL, city VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE blood_stock(id INT PRIMARY KEY AUTO_INCREMENT, blood_group VARCHAR(5) NOT NULL UNIQUE, units INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE blood_requests(id INT PRIMARY KEY AUTO_INCREMENT, donor_id INT NOT NULL, patient_name VARCHAR(100) NOT NULL, blood_group VARCHAR(5) NOT NULL, units_needed INT NOT NULL, hospital_name VARCHAR(150) NOT NULL, contact_phone VARCHAR(20) NOT NULL, notes VARCHAR(255), status VARCHAR(20) NOT NULL DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_request_donor FOREIGN KEY(donor_id) REFERENCES donors(id) ON DELETE CASCADE);
